<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import type { LocalRelocationPlanPhase, LocalRelocationResourceRole, LocalRelocationResourceState, LocalRelocationSourceDisposition } from '@music-bridge/contracts'
import type { useLocalRelocationPlans } from '../../composables/application/useLocalRelocationPlans.js'

const props = defineProps<{ session: ReturnType<typeof useLocalRelocationPlans> }>()
const emit = defineEmits<{ 'return-focus': [] }>()
const dialog = ref<HTMLDialogElement>(), heading = ref<HTMLElement>()
const plan = computed(() => props.session.plan.value), locked = computed(() => props.session.locked.value)
const roleLabel: Record<LocalRelocationResourceRole, string> = { AUDIO: '音频原文件', CUE: 'CUE段落索引', LYRIC: '歌词', IMAGE: '图片', DIRECTORY_SHARED_COVER: '共享目录封面', MANIFEST: '清单', UNKNOWN_REFERENCE: '尚未核实的引用' }
const resourceState: Record<LocalRelocationResourceState, string> = { pending: '尚未处理', deferred: '已延期', moving: '正在处理', verified: '目标已核验', registered: '新位置已登记', retained: '源材料已保留', cleaned: '本次源已清理', unchanged: '保持原状', failed: '未完成', unknown: '结果未知' }
const phaseLabel: Record<LocalRelocationPlanPhase, string> = { PLANNED: '具体预览', RESERVED: '空间与保护已预留', SOURCE_VERIFIED: '原文件已核验', SOURCE_CAPTURED: '原文件已保全', TARGET_STAGED: '新文件已准备', TARGET_SYNCED: '目标已同步', TARGET_INSTALLED: '目标已安装，等待回读', VERIFIED_TARGET: '目标完整回读已通过', REGISTERED: '新位置已登记', SOURCE_RETAINED: '源材料保留', CLEANUP_REQUESTED: '本次具体清理已受理', SOURCE_REMOVED: '本次源已清理', DIRECTORY_SYNCED: '目录已同步', TERMINAL: '处理已结束', UNKNOWN: '阶段未知' }
const handling = { unchanged: '原源保持', 'move-pending': '尚未处理原源', retained: '原源保留', 'cleanup-eligible': '原源保留，可另行具体清理', removed: '本次原源已清理', unknown: '原源状态未知' }
const verification = { unverified: '尚未核验', 'verified-source': '原源已完整核验', 'verified-target': '目标已独立完整回读', unknown: '核验结果未知' }
const recoveryActionLabel = { reconcile: '对账已处理的文件与登记结果', rollback: '按完整材料回退原位置', 'keep-target': '保留目标并继续核验登记' }
const text = (event: Event): string => (event.target as HTMLInputElement | HTMLSelectElement).value
let returnFocus: HTMLElement | null = null
function close(): void { props.session.close() }
function keydown(event: KeyboardEvent): void {
  if (event.key !== 'Tab' || !dialog.value) return
  const entries = Array.from(dialog.value.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), summary, [tabindex="0"]')).filter(element => element.getClientRects().length > 0)
  const first = entries[0], last = entries.at(-1)
  if (!first) { event.preventDefault(); heading.value?.focus(); return }
  if (event.shiftKey && (document.activeElement === first || document.activeElement === heading.value)) { event.preventDefault(); last?.focus() }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() }
}
onMounted(async () => { returnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null; await nextTick(); dialog.value?.showModal(); heading.value?.focus() })
onBeforeUnmount(() => { dialog.value?.close(); if (returnFocus?.isConnected) returnFocus.focus({ preventScroll: true }); else emit('return-focus') })
</script>

<template>
  <dialog ref="dialog" class="local-relocation-dialog" aria-labelledby="local-relocation-heading" aria-describedby="local-relocation-boundary" @cancel.prevent="close" @keydown="keydown">
    <header><div><p class="muted">本地音乐 · 具体计划</p><h2 id="local-relocation-heading" ref="heading" tabindex="-1">文件搬迁与重关联</h2></div><button type="button" aria-label="关闭文件搬迁" @click="close">关闭</button></header>
    <p id="local-relocation-boundary" class="muted">逐项处理音频和伴随文件，保留曲目身份与历史引用。文件处理和位置登记分阶段完成；中断时保留可核对的材料。</p>
    <p v-if="session.targetLabel.value">{{ session.targetLabel.value }}</p>
    <p v-if="session.context.value" class="muted">文件搬迁开关：{{ session.context.value.policy.enabled ? '已开启' : '已关闭（默认）' }}{{ session.context.value.policy.draining ? ' · 正在安全收尾' : '' }}。资格{{ session.qualified.value ? '已核验' : '尚未通过' }}。</p>
    <p v-if="session.context.value?.qualification.issue" role="status">{{ session.issue(session.context.value.qualification.issue) }}</p>
    <p v-if="session.loading.value" role="status">正在读取持久计划与逐项结果…</p>
    <form v-if="session.view.value === 'edit'" aria-label="具体文件搬迁内容" @submit.prevent="session.preview()">
      <label v-if="session.mode.value === 'rename' || session.mode.value === 'move'">文件动作<select aria-label="文件搬迁动作" :value="session.mode.value" :disabled="locked" @change="session.setMode(text($event) as 'rename' | 'move')"><option value="move">移动到明确选择的目录</option><option v-if="session.targets.value.length === 1" value="rename">重命名这份源文件</option></select></label>
      <p v-else-if="session.mode.value === 'root-reassociate'" class="muted">核对目录的底层卷或共享身份与新位置；整根对象及历史记录保留，同名挂载目录须独立验证。</p>
      <p v-else class="muted">这是新的同内容位置计划；原外部找回候选继续保留独立身份，不会按同名或相同Hash自动合并。</p>
      <label v-if="session.mode.value === 'rename'">新文件名<input aria-label="搬迁新文件名" :value="session.newName.value" :disabled="locked" maxlength="512" autocomplete="off" @input="session.setNewName(text($event))"><span class="muted">填写包含原扩展名的一个文件名，保留输入的大小写和Unicode；原音频字节不改。</span></label>
      <div v-else class="target-choice"><button type="button" :disabled="locked" @click="session.chooseTarget()">{{ session.choosing.value ? '正在选择目标…' : session.mode.value === 'locate' ? '选择具体找回文件' : session.mode.value === 'root-reassociate' ? '选择重关联目标目录' : '选择搬迁目标目录' }}</button><span v-if="session.targetChoice.value">{{ session.targetChoice.value.label }}</span><span v-else class="muted">尚未选择具体目标。</span><p v-if="session.choiceExpired.value" role="status">目标选择已过期，请重新选择；不会续签原请求。</p></div>
      <label v-if="session.mode.value === 'rename' || session.mode.value === 'move'">源材料处理<select aria-label="搬迁源材料处理" :value="session.sourceDisposition.value" :disabled="locked" @change="session.setDisposition(text($event) as LocalRelocationSourceDisposition)"><option value="RETAIN">保留源材料（默认）</option><option value="REQUEST_CLEANUP">目标验证并登记后，再具体清理源材料</option></select></label>
      <p class="muted">完整预览包含音频、CUE、歌词、图片与清单引用。未知引用或未证明的共享资源会阻止整个计划；活动播放、暂停读取、预取及录音保护会阻止或延期处理。</p>
      <button type="submit" :disabled="!session.canPreview.value">{{ session.previewing.value ? '正在受理具体预览…' : '预览具体搬迁计划' }}</button>
    </form>
    <section v-if="session.view.value === 'history'" aria-label="搬迁持久历史"><p v-if="session.historyLoaded.value && !session.history.value.length && !session.loading.value">还没有文件搬迁计划。</p><ul><li v-for="entry in session.history.value" :key="entry.planId" :data-relocation-plan-id="entry.planId"><span>{{ entry.operations }} 项 · {{ session.stateLabel(entry.state) }}</span><button type="button" :disabled="session.busy.value" :aria-label="`查看搬迁计划 ${entry.planId}`" @click="session.loadPlan(entry.planId)">查看计划</button></li></ul><button v-if="session.historyCursor.value" type="button" :disabled="session.busy.value" @click="session.loadHistory(true)">下一页搬迁历史</button></section>
    <section v-if="session.view.value === 'plan' && plan" aria-label="搬迁具体预览与逐项结果" :data-relocation-plan-id="plan.planId">
      <header><h3>{{ plan.intent.kind === 'recovery' ? '新的具体恢复预览' : '具体文件计划' }} · {{ plan.items.length }} 项</h3><strong role="status">{{ session.stateLabel(plan.state) }}</strong></header>
      <div v-if="plan.intent.kind === 'recovery'" aria-label="本次具体恢复动作"><p>这是关联原计划的新的具体恢复预览，仍需最终确认才会处理文件。</p><p v-if="session.recoveryAction.value">本次动作：{{ recoveryActionLabel[session.recoveryAction.value.action] }} · {{ session.recoveryAction.value.label }}。下方逐项列出完整材料与处理结果。</p><p class="muted">原未知命令继续保留并只读核对；新恢复命令受理后，文件、位置登记与材料保护仍须逐项完成。</p></div><p v-if="session.planExpired.value" role="status">此具体预览已过期，请重新生成完整计划。</p>
      <p class="muted">资源闭集{{ plan.closure.complete ? '完整' : '未完整' }}：{{ plan.closure.resourceCount }} 个资源、{{ plan.closure.referenceEdgeCount }} 条引用、{{ plan.closure.rootCount }} 个根；源材料共 {{ plan.closure.totalSourceBytes }} 字节。空间{{ plan.closure.spaceVerified ? '已核验' : '尚未核实' }}，保护{{ plan.closure.protection === 'verified' ? '已核验' : plan.closure.protection === 'blocked' ? '阻止处理' : '未知' }}。</p>
      <p v-for="(issue, index) in plan.issues" :key="`${issue.code}-${index}`" role="alert">{{ session.issue(issue) }}</p>
      <article v-for="item in plan.items" :key="item.operationId" class="operation" :data-relocation-operation-id="item.operationId"><h4>{{ item.sourceLabel }}</h4><p>目标：{{ item.targetLabel }}</p><p>{{ resourceState[item.state] }} · {{ phaseLabel[item.phase] }}<span v-if="item.issue"> · {{ session.issue(item.issue) }}</span></p><p class="muted">此项涉及 {{ item.resourceIds.length }} 个完整资源；曲目身份、收藏歌单和已保存的历史来源保留。</p></article>
      <div class="table-wrap"><table><caption>完整资源闭集与实际逐项结果</caption><thead><tr><th scope="col">资源</th><th scope="col">状态与阶段</th><th scope="col">完整验证</th><th scope="col">源材料</th></tr></thead><tbody><tr v-for="resource in plan.resources" :key="resource.resourceId" :data-relocation-resource-id="resource.resourceId"><th scope="row">{{ resource.label }}<br><span class="muted">{{ roleLabel[resource.role] }} · {{ resource.bytes ?? '大小未知' }}{{ resource.bytes === null ? '' : ' 字节' }}</span></th><td>{{ resourceState[resource.state] }}<br>{{ phaseLabel[resource.phase] }}<p v-if="resource.issue" role="status">{{ session.issue(resource.issue) }}</p></td><td>{{ verification[resource.verification] }}<br><span class="muted">{{ resource.contentEffect === 'reference-rewritten' ? '仅修改计划内伴随引用' : resource.contentEffect === 'whole-bytes-preserved' ? '完整原字节保持' : '不改内容' }}</span></td><td>{{ handling[resource.sourceHandling] }}</td></tr></tbody></table></div>
      <p v-if="plan.referenceEdges.some(edge => edge.shared)" class="muted">本计划包含共享伴随引用；未证明的共享依赖不清理。</p>
      <section aria-label="本计划源材料清理"><h4>源材料与具体清理</h4><p v-if="['source-retained', 'eligible'].includes(plan.cleanup.state)">目标与源材料分别保留；清理需要再次确认当前已验证目标和本次源资源。</p><p v-if="plan.cleanup.state === 'eligible'" class="muted">上方已验证并登记的目标允许另行清理 {{ plan.cleanup.sourceResourceIds.length }} 个本计划源资源；点击具体清理按钮会重新读取当前状态，再申请新的清理能力。</p><p v-else-if="plan.cleanup.state === 'running'" role="status">本次具体清理正在处理，逐项结果以上表为准。</p><p v-else-if="plan.cleanup.state === 'completed'" role="status">本次具体清理已完成，请核对上方各资源状态。</p><p v-else-if="plan.cleanup.state === 'unknown'" role="status">清理结果未知，只读取原命令；源与目标材料按逐项状态保留。</p><p v-else-if="plan.cleanup.state === 'unavailable'" class="muted">目标尚未完整验证并登记，不能清理源材料。</p><p v-if="plan.cleanup.issue" role="alert">{{ session.issue(plan.cleanup.issue) }}</p></section>
      <section v-if="plan.recoveryChoices.length" aria-label="明确恢复选择"><h4>新的具体恢复计划</h4><p class="muted">每项选择须核对当前原计划与全部相关材料；预览不处理文件，完成预览后另行具体确认。</p><article v-for="choice in plan.recoveryChoices" :key="choice.choiceId"><p>{{ recoveryActionLabel[choice.action] }} · {{ choice.resourceIds.length }} 个相关资源</p><button type="button" :disabled="!session.canPreviewRecovery(choice)" @click="session.previewRecovery(choice)">预览恢复：{{ choice.label }}</button></article></section>
      <details @toggle="($event.target as HTMLDetailsElement).open && !session.eventsLoaded.value && session.loadEvents()"><summary>逐项处理历史</summary><ol><li v-for="event in session.events.value" :key="event.eventId">{{ event.label }} · {{ phaseLabel[event.phase] }}<span v-if="event.issue"> · {{ session.issue(event.issue) }}</span></li></ol><button v-if="session.eventCursor.value" type="button" :disabled="session.busy.value" @click="session.loadEvents(true)">更多处理历史</button></details>
      <p v-if="['SOURCE_RETAINED', 'COMPLETED'].includes(plan.state)" class="muted">新位置按逐项登记结果生效；Roon重新直送与实际听感另行确认。</p>
    </section>
    <p v-if="session.error.value" role="alert">{{ session.error.value }}</p><p v-if="session.notice.value" role="status">{{ session.notice.value }}</p><p v-if="session.unknown.value" role="status">原命令结果未知。关闭只结束此处等待；重新读取只核对原命令，不会自动重签、重放或清理原件。</p>
    <footer><button type="button" :disabled="session.busy.value" @click="session.reconcile()">重新读取搬迁结果</button><button type="button" :disabled="session.busy.value" @click="session.loadHistory()">搬迁历史</button><button v-if="session.canCancel.value" type="button" @click="session.cancel()">取消这份搬迁计划</button><button v-if="plan && ['READY', 'BLOCKED', 'DEFERRED'].includes(plan.state) && (session.targets.value.length || session.rootTarget.value)" type="button" :disabled="locked" @click="session.edit()">返回搬迁编辑</button><button v-if="plan" type="button" class="primary" :disabled="!session.canConfirm.value" @click="session.confirm()">{{ session.confirming.value ? '正在提交具体确认…' : '确认这份搬迁计划' }}</button><button v-if="plan && plan.cleanup.state !== 'unavailable'" type="button" class="cleanup" :disabled="!session.canCleanup.value" @click="session.cleanup()">{{ session.cleaning.value ? '正在提交具体清理…' : '清理这份已验证计划的源副本' }}</button></footer>
  </dialog>
</template>

<style scoped>
.local-relocation-dialog{box-sizing:border-box;width:min(1020px,calc(100vw - 32px));max-height:calc(100dvh - 32px);padding:26px;border:1px solid var(--mb-glass-border);border-radius:20px;background:var(--mb-glass-clear);color:var(--mb-text-primary);backdrop-filter:blur(30px);overflow:auto;overscroll-behavior:contain}.local-relocation-dialog::backdrop{background:#10182866}header,footer,.target-choice{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}header h2{margin:0}.muted{color:var(--mb-text-secondary);line-height:1.6}form{display:grid;gap:16px}label{display:grid;gap:8px}input,select,button{box-sizing:border-box;min-height:44px;min-width:44px;padding:8px 12px;border:1px solid var(--mb-glass-border);border-radius:8px;background:var(--mb-glass-clear);color:inherit;font:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible,h2:focus-visible{outline:2px solid var(--mb-accent);outline-offset:3px}.primary{background:var(--mb-accent);color:var(--mb-text-on-accent,#fff)}.cleanup{border-color:var(--mb-accent)}.operation{padding:12px 0;border-bottom:1px solid var(--mb-divider)}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px}caption{text-align:left;padding:12px 0}th,td{text-align:left;vertical-align:top;padding:12px 8px;overflow-wrap:anywhere;border-bottom:1px solid var(--mb-divider)}ul{list-style:none;padding:0}li{display:flex;gap:12px;justify-content:space-between;padding:10px 0}footer{margin-top:24px;padding-top:16px;border-top:1px solid var(--mb-divider)}@media(max-width:640px){.local-relocation-dialog{padding:18px}th,td{min-width:120px}}
</style>
